```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = format!(
            "Digest {}: {} entries. {}",
            composed.date,
            composed.entries.len(),
            composed.overview
        );
        let published = notifier::notify(&message);
        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
